const logoMap = {
  aws: AwsLogo,
  azure: AzureLogo,
  linux: LinuxLogo,
  docker: DockerLogo,
  k8s: KubernetesLogo,
  terraform: TerraformLogo,
  ansible: AnsibleLogo,
  prometheus: PrometheusLogo,
  grafana: GrafanaLogo,
  proxmox: ProxmoxLogo,
} as const;

export type TechLogoId = keyof typeof logoMap;

export function TechLogo({
  id,
  className,
}: {
  id: TechLogoId;
  className?: string;
}) {
  const Logo = logoMap[id];
  if (!Logo) return null;
  return <Logo className={cn("h-7 w-7", className)} />;
}
